from .checker import ModelChecker


class objectmodelchecker(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self.model_checker = ModelChecker()

    def verify_scf_parameters_with_nidd_database(self, product, domain, sw_release, scf_xml_path):
        """
        Verify parameters found in SCF managed objects with NIDD database.
        :param product: Product name in NIDD terms ie. NRBTS
        :param domain: Domain name in NIDD terms ie. 5GNB
        :param sw_release: Official name of Software Release ie. 5G18 or 5G18A etc. (For NIDD sw package resolving.)
        :param scf_xml_path: Path to xml file
        :return: CheckReport object with result status and error_data

        check parameter_value_is_not_default_value:
        Checks if parameter value from scf has different value from the default value in NIDD.\
        If it has error_data is added to the CheckReport.
        If default_value in NIDD doesn't exist then the check is skipped.
        If parameter doesn't exist in NIDD, the check is skipped.
        """

        return self.model_checker.check_scf_parameters_vs_nidd(
            product=product,
            domain=domain,
            sw_release=sw_release,
            scf_xml_path=scf_xml_path
        )
